import android.media.MediaRouter;
import android.content.Context;
import android.content.ContextWrapper;
public final class MediaRouterSmoke {
 private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 public static void main(String[] args){Context context=new ContextWrapper(null);MediaRouter router=MediaRouter.shirazForHost(context);MediaRouter.RouteInfo route=router.getDefaultRoute();check(router.getRouteCount()==1&&router.getRouteAt(0)==route&&router.getSelectedRoute(1)==route,"one default host route");check(route.isDefault()&&route.isEnabled()&&!route.isConnecting()&&route.getPlaybackType()==0,"local enabled output");check(route.matchesTypes(1)&&!route.matchesTypes(2)&&route.getPresentationDisplay()==null,"remote video not advertised");check(route.getVolumeHandling()==0&&route.getVolume()==route.getVolumeMax(),"fixed-volume capability");route.setTag("test");check("test".equals(route.getTag()),"route tag");check(route.getCategory().getRoutes(null).get(0)==route,"category enumeration");final int[] changes={0};MediaRouter.Callback callback=new MediaRouter.SimpleCallback(){public void onRouteSelected(MediaRouter r,int types,MediaRouter.RouteInfo value){changes[0]++;}};router.addCallback(1,callback);router.addCallback(1,callback,2);router.selectRoute(1,route);route.select();router.removeCallback(callback);check(changes[0]==0,"no false route changes");boolean remote=false;try{router.createUserRoute(router.createRouteCategory("remote",false));}catch(UnsupportedOperationException expected){remote=true;}check(remote,"unsupported remote route explicit");check(Context.MEDIA_ROUTER_SERVICE.equals(context.getSystemServiceName(MediaRouter.class)),"typed service mapping");System.out.println("MEDIA_ROUTER_LOCAL_OUTPUT_OK");}
}
